/* Configurable consultant export: every download is bound to a checked preview. */
let payrollRequest=0,payrollDrafts={},payrollPeriod=null,payrollPreview=null,payrollOwner='';
const payrollCanAccess=()=>['admin','manager','hr'].includes(auth?.user?.role);
const payrollHasChanges=()=>auth?.user?.id===payrollOwner&&Object.values(payrollDrafts).some(d=>d.dirty);
window.addEventListener('beforeunload',e=>{if(payrollHasChanges()){e.preventDefault();e.returnValue=''}});
function payrollInvalidate(d){d.dirty=true;d.connectorConfirmed=false;if($('#payrollConnectorConfirm'))$('#payrollConnectorConfirm').checked=false;payrollPreview=null;if($('#payrollSaveState'))$('#payrollSaveState').textContent='Modifiche da salvare';if($('#payrollPreviewResult'))$('#payrollPreviewResult').innerHTML='<p class="note">Modello modificato. Salva una nuova versione e rigenera l’anteprima.</p>'}

async function renderPayroll(){
 if(!payrollCanAccess())throw Error('Pagina riservata a HR e responsabili autorizzati.');
 if(payrollOwner!==auth.user.id){payrollDrafts={};payrollPeriod=null;payrollPreview=null;payrollOwner=auth.user.id}
 const request=++payrollRequest,selectedCenter=cid;
 if(!payrollPeriod)payrollPeriod={first:month,last:month};
 $('#content').innerHTML='<div class="panel" role="status">Caricamento del modello paghe…</div>';
 const data=await api('payroll_config?'+new URLSearchParams({cid:selectedCenter}));
 if(request!==payrollRequest||tab!=='paghe'||cid!==selectedCenter)return;
 let d=payrollDrafts[selectedCenter];
 if(!d||!d.dirty)d=payrollDrafts[selectedCenter]={config:structuredClone(data.config),version:data.version,dirty:false};
 d.config.connector??=payrollDefaultConnector();const cfg=d.config,stale=d.version!==data.version,fields=Object.fromEntries(data.fields.map(f=>[f.id,f]));
 $('#monthPick').closest('.actions').hidden=true;
 $('#content').innerHTML=`<div class="payroll-page"><section class="panel"><span class="eyebrow">PREPARAZIONE PER IL CONSULENTE</span><h2>Un modello da verificare insieme.</h2><p class="muted">Prepara la corrispondenza di causali, matricole e colonne. Il modello generico resta disponibile; per un tracciato del consulente servono il gestionale destinatario e le specifiche verificate. Non vengono calcolati netto o contributi.</p><div class="note">Una riga per fascia a consuntivo. Ore lavorate e crediti per assenza restano separati; un campo vuoto significa dato non disponibile.</div></section><section class="panel"><div class="toolbar"><h2>Modello del centro ${esc(data.center)}</h2><span class="tag">Versione salvata ${data.version}</span></div>${stale?'<p class="error">Un altro utente ha aggiornato il modello. Le tue modifiche sono ancora visibili, ma occorre ricaricare la versione salvata prima di procedere.</p>':''}<form id="payrollConfigForm"><div id="payrollConnector"></div><div class="payroll-fields"><label class="payroll-wide">Nome del modello<input id="payrollName" maxlength="120" value="${esc(cfg.name)}" required></label><label>Stato<select id="payrollStatus"><option value="draft" ${cfg.status==='draft'?'selected':''}>Bozza da concordare</option><option value="confirmed" ${cfg.status==='confirmed'?'selected':''}>Verificato con il consulente</option></select></label><label>Separatore CSV<select id="payrollDelimiter"><option value=";" ${cfg.delimiter===';'?'selected':''}>Punto e virgola (;)</option><option value="," ${cfg.delimiter===','?'selected':''}>Virgola (,)</option><option value="tab" ${cfg.delimiter==='\t'?'selected':''}>Tabulazione</option></select></label><label>Separatore decimale<select id="payrollDecimal"><option value="," ${cfg.decimal_separator===','?'selected':''}>Virgola (6,5)</option><option value="." ${cfg.decimal_separator==='.'?'selected':''}>Punto (6.5)</option></select></label><label class="payroll-wide">Riferimento alla verifica con il consulente<textarea id="payrollConfirmation" maxlength="1000" placeholder="Es. specifiche ricevute il …, referente …">${esc(cfg.confirmation_note)}</textarea><small>Obbligatorio per confermare il modello: almeno 8 caratteri.</small></label></div><details open class="payroll-section"><summary>Colonne e ordine del tracciato</summary><p class="muted smalltext">Le colonne obbligatorie garantiscono l’identificazione di modello, centro, persona, data e causale.</p><div id="payrollColumns"></div><div class="actions" id="payrollAddColumnArea"><label for="payrollAddField">Aggiungi colonna</label><select id="payrollAddField"></select><button type="button" class="btn" id="payrollAddColumn">Aggiungi</button><button type="button" class="btn" id="payrollAddExpected">Aggiungi intestazione consulente</button></div></details><details open class="payroll-section"><summary>Corrispondenza delle causali</summary><p class="muted smalltext">Inserisci i codici richiesti dal consulente. Le causali presenti nei consuntivi devono avere una corrispondenza.</p><div class="table-scroll"><table class="data-table"><thead><tr><th>Causale registro</th><th>Tipo</th><th>Codice paghe</th></tr></thead><tbody>${data.causes.map((c,i)=>`<tr><td><b>${esc(c.id)}</b> · ${esc(c.label)}</td><td>${esc({work:'Lavoro',absence:'Assenza',rest:'Riposo'}[c.kind]||c.kind)}</td><td><input data-payroll-cause="${i}" value="${esc(cfg.causes[c.id]||'')}" maxlength="100" aria-label="Codice paghe per ${esc(c.label)}"></td></tr>`).join('')}</tbody></table></div></details><details class="payroll-section"><summary>Matricole paghe delle persone (${data.people.length})</summary><p class="muted smalltext">Lascia vuoto per usare la matricola dell’anagrafica. L’eventuale codice inserito qui vale solo per questo modello.</p><div class="table-scroll"><table class="data-table"><thead><tr><th>Persona</th><th>Matricola anagrafica</th><th>Matricola paghe alternativa</th></tr></thead><tbody>${data.people.map((p,i)=>`<tr><td>${esc(p.name)}</td><td>${esc(p.registration||'Mancante')}</td><td><input data-payroll-registration="${i}" value="${esc(cfg.registrations[p.id]||'')}" placeholder="${esc(p.registration||'Da indicare')}" maxlength="100" aria-label="Matricola paghe per ${esc(p.name)}"></td></tr>`).join('')||'<tr><td colspan="3">Nessuna anagrafica disponibile.</td></tr>'}</tbody></table></div></details><div class="payroll-footer"><span id="payrollSaveState" role="status">${d.dirty?'Modifiche da salvare':'Modello salvato · '+(cfg.status==='draft'?'bozza':'verificato')}</span><div class="actions"><button type="button" class="btn" id="payrollReload">Ricarica modello salvato</button><button type="submit" class="btn primary" id="payrollSave" ${stale?'disabled':''}>Salva nuova versione</button></div></div><div id="payrollConfigError" role="alert"></div></form>${data.history.length?`<details class="payroll-section"><summary>Versioni precedenti (${data.history.length} più recenti)</summary><ul>${data.history.map(h=>`<li>Versione ${h.version} · ${esc(h.name)} · ${h.status==='confirmed'?'verificato':'bozza'} · ${esc(new Date(h.created_at).toLocaleString('it-IT'))} · ${esc(h.created_by)}</li>`).join('')}</ul></details>`:''}</section><section class="panel"><h2>Anteprima e controlli</h2><form id="payrollPreviewForm" class="payroll-period"><label>Dal mese<input type="month" id="payrollFrom" value="${esc(payrollPeriod.first)}" required></label><label>Al mese<input type="month" id="payrollTo" value="${esc(payrollPeriod.last)}" required></label><button class="btn primary" type="submit" id="payrollPreviewLoad">Genera anteprima</button></form><p class="muted smalltext">Massimo 24 mesi. Il download richiede un modello verificato, nessun controllo bloccante e un’anteprima aggiornata. Se il flusso approvazioni è attivo, ogni mese deve essere approvato da HR e chiuso.</p><div id="payrollPreviewResult" aria-live="polite"></div></section></div>`;
 function showColumns(){payrollRenderColumns(cfg,data,fields,d,showColumns)}
 payrollRenderConnector(cfg,d,selectedCenter,request,showColumns);
 showColumns();
 $('#payrollAddColumn').onclick=()=>{const f=fields[$('#payrollAddField').value];if(f){cfg.columns.push({field:f.id,label:f.label});if(cfg.connector.mode==='consultant')cfg.connector.expected_columns.push({header:f.label,type:f.type,required:false,max_length:null});payrollInvalidate(d);showColumns()}};
 $('#payrollAddExpected').onclick=()=>{let label='Nuova colonna',n=1;while(cfg.columns.some(c=>c.label===label))label='Nuova colonna '+(++n);cfg.columns.push({field:'',label});cfg.connector.expected_columns.push({header:label,type:'text',required:true,max_length:null});payrollInvalidate(d);showColumns()};
 for(const [selector,key] of [['#payrollName','name'],['#payrollStatus','status'],['#payrollConfirmation','confirmation_note'],['#payrollDecimal','decimal_separator'],['#payrollDelimiter','delimiter']])$(selector).oninput=e=>{cfg[key]=key==='delimiter'&&e.target.value==='tab'?'\t':e.target.value;payrollInvalidate(d);if(key==='status')payrollConnectorVisibility(cfg)};
 document.querySelectorAll('[data-payroll-cause]').forEach(el=>el.oninput=()=>{cfg.causes[data.causes[+el.dataset.payrollCause].id]=el.value;payrollInvalidate(d)});
 document.querySelectorAll('[data-payroll-registration]').forEach(el=>el.oninput=()=>{cfg.registrations[data.people[+el.dataset.payrollRegistration].id]=el.value;payrollInvalidate(d)});
 $('#payrollReload').onclick=()=>{if(d.dirty&&!confirm('Scartare le modifiche locali e caricare il modello salvato?'))return;delete payrollDrafts[selectedCenter];payrollPreview=null;renderPayroll().catch(e=>toast(e.message))};
 $('#payrollConfigForm').onsubmit=async e=>{e.preventDefault();const button=$('#payrollSave'),form=e.currentTarget;button.disabled=true;form.inert=true;$('#payrollConfigError').textContent='';try{if(cfg.connector.mode==='consultant'&&cfg.status==='confirmed'&&!d.connectorConfirmed)throw Error('Conferma di aver verificato questa versione con il consulente.');await api('payroll_save',{cid:selectedCenter,expected_version:d.version,config:structuredClone(cfg),confirm_connector:!!d.connectorConfirmed});delete payrollDrafts[selectedCenter];payrollPreview=null;if(tab==='paghe'&&cid===selectedCenter)await renderPayroll();toast('Nuova versione del modello salvata. Genera l’anteprima.')}catch(x){if($('#payrollConfigError'))$('#payrollConfigError').innerHTML='<p class="error">'+esc(x.message)+'</p>'}finally{form.inert=false;if(button.isConnected)button.disabled=false}};
 for(const [selector,key] of [['#payrollFrom','first'],['#payrollTo','last']])$(selector).onchange=e=>{payrollPeriod[key]=e.target.value;payrollPreview=null;$('#payrollPreviewResult').textContent='Periodo cambiato: genera una nuova anteprima.'};
 $('#payrollPreviewForm').onsubmit=async e=>{e.preventDefault();const button=$('#payrollPreviewLoad');button.disabled=true;payrollPreview=null;try{if(d.dirty)throw Error('Salva le modifiche al modello prima di generare l’anteprima.');const query={cid:selectedCenter,from:payrollPeriod.first,to:payrollPeriod.last};const p=await api('payroll_preview?'+new URLSearchParams(query));if(request!==payrollRequest||tab!=='paghe'||cid!==selectedCenter||query.from!==payrollPeriod.first||query.to!==payrollPeriod.last||d.dirty)return;payrollPreview=p;payrollShowPreview(p)}catch(x){if(request===payrollRequest&&$('#payrollPreviewResult'))$('#payrollPreviewResult').innerHTML='<p class="error">'+esc(x.message)+'</p>'}finally{if(button.isConnected)button.disabled=false}};
 if(payrollPreview&&payrollPreview.cid===selectedCenter&&payrollPreview.version===d.version&&!d.dirty&&payrollPreview.first===payrollPeriod.first&&payrollPreview.last===payrollPeriod.last)payrollShowPreview(payrollPreview);
}

function payrollShowPreview(p){
 const s=p.summary;
 $('#payrollPreviewResult').innerHTML=`<div class="payroll-summary"><div><strong>${s.rows}</strong><span>righe</span></div><div><strong>${s.people}</strong><span>persone</span></div><div><strong>${s.known_minutes===null?'—':(s.known_minutes/60).toLocaleString('it-IT',{maximumFractionDigits:2})}</strong><span>ore note</span></div><div><strong>${s.blocking_issues}</strong><span>controlli bloccanti</span></div><div><strong>${s.warnings}</strong><span>avvertenze</span></div></div><p><b>${esc(p.template_name)} · versione ${p.version}</b> · ${esc(p.first)} / ${esc(p.last)}</p>${payrollFormatDescription(p)}${p.issues.length?`<div class="payroll-issues"><h3>Da controllare</h3><ul>${p.issues.map(i=>`<li class="${i.severity==='error'?'payroll-blocker':''}"><b>${i.severity==='error'?'Bloccante':'Avvertenza'}</b>${i.day?' · '+esc(i.day):''}: ${esc(i.message)}</li>`).join('')}</ul>${p.shown_issues<s.blocking_issues+s.warnings?'<p>Mostrati i primi 200 controlli. Il totale considera l’intero periodo.</p>':''}</div>`:'<p class="note">Nessun controllo da risolvere.</p>'}<div class="table-scroll payroll-preview-table"><table class="data-table"><thead><tr>${p.columns.map(c=>`<th>${esc(c.label)}</th>`).join('')}</tr></thead><tbody>${p.rows.map(row=>`<tr>${row.map((v,i)=>`<td>${v===null?'<span class="muted" aria-label="Dato non disponibile">—</span>':esc(payrollFormatValue(v,p.columns[i],p.output_format))}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${p.columns.length}">Nessun consuntivo.</td></tr>`}</tbody></table></div><p class="muted smalltext">Mostrate ${p.shown_rows} di ${s.rows} righe. Il file contiene l’intero periodo. Le avvertenze vanno verificate prima della consegna.</p><div class="actions"><button class="btn primary" data-payroll-download="csv" ${p.can_download?'':'disabled'}>Scarica CSV</button><button class="btn" data-payroll-download="xlsx" ${p.can_download?'':'disabled'}>Scarica Excel</button></div>${p.can_download?'':'<p class="note">Download sospeso: risolvi i controlli bloccanti e genera nuovamente l’anteprima.</p>'}`;
 document.querySelectorAll('[data-payroll-download]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{if(payrollPreview!==p||payrollDrafts[p.cid]?.dirty)throw Error('Genera una nuova anteprima prima del download.');const format=button.dataset.payrollDownload;await downloadFile('payroll_download?'+new URLSearchParams({cid:p.cid,from:p.first,to:p.last,format,fingerprint:p.fingerprint}),`Paghe_${p.center_code}_${p.first}_${p.last}_v${p.version}.${format}`);toast('File paghe pronto per il download.')}catch(e){toast(e.message)}finally{if(button.isConnected)button.disabled=!p.can_download}});
}

function payrollDefaultConnector(){return {mode:'generic',provider:'',format_name:'',format_version:'',specification_reference:'',expected_columns:[],date_format:'YYYY-MM-DD',encoding:'utf-8-sig'}}
function payrollConnectorVisibility(cfg){
 const consultant=cfg.connector.mode==='consultant';
 if($('#payrollConnectorDetails'))$('#payrollConnectorDetails').hidden=!consultant;
 if($('#payrollConnectorAttestation'))$('#payrollConnectorAttestation').hidden=!consultant||cfg.status!=='confirmed';
 if($('#payrollAddExpected'))$('#payrollAddExpected').hidden=!consultant;
}
function payrollRenderConnector(cfg,d,selectedCenter,request,showColumns){
 const connector=cfg.connector;
 $('#payrollConnector').innerHTML=`<section class="payroll-connector"><label for="payrollConnectorMode">Destinazione del file</label><select id="payrollConnectorMode"><option value="generic" ${connector.mode==='generic'?'selected':''}>Modello generico</option><option value="consultant" ${connector.mode==='consultant'?'selected':''}>Tracciato del consulente</option></select><p class="muted smalltext">Il file viene scaricato sul tuo computer. La consegna al consulente e l’importazione nel suo gestionale restano a cura dell’ufficio HR.</p><div id="payrollConnectorDetails"><div class="payroll-fields"><label>Gestionale destinatario<input id="payrollProvider" value="${esc(connector.provider)}" maxlength="120" placeholder="Da chiedere al consulente"></label><label>Nome tracciato<input id="payrollFormatName" value="${esc(connector.format_name)}" maxlength="120"></label><label>Versione specifiche<input id="payrollFormatVersion" value="${esc(connector.format_version)}" maxlength="80"></label><label class="payroll-wide">Riferimento alle specifiche<input id="payrollSpecificationReference" value="${esc(connector.specification_reference)}" maxlength="500" placeholder="Documento e data forniti dal consulente"></label><label>Formato delle date<select id="payrollDateFormat"><option value="YYYY-MM-DD" ${connector.date_format==='YYYY-MM-DD'?'selected':''}>AAAA-MM-GG</option><option value="DD/MM/YYYY" ${connector.date_format==='DD/MM/YYYY'?'selected':''}>GG/MM/AAAA</option></select></label><label>Codifica del CSV<select id="payrollEncoding"><option value="utf-8-sig" ${connector.encoding==='utf-8-sig'?'selected':''}>UTF-8 con BOM</option><option value="utf-8" ${connector.encoding==='utf-8'?'selected':''}>UTF-8</option><option value="cp1252" ${connector.encoding==='cp1252'?'selected':''}>Windows-1252</option></select></label></div><details class="payroll-section"><summary>Leggi le intestazioni o un file di specifiche</summary><p class="muted smalltext">Usa un file UTF-8 fino a 32 KiB con la sola riga delle intestazioni CSV, oppure la specifica JSON esportata da questa pagina. La lettura sostituisce le colonne della bozza; il modello salvato cambia solo quando salvi una nuova versione.</p><div class="payroll-fields"><label>Contenuto<select id="payrollSpecKind"><option value="csv_header">Sola intestazione CSV</option><option value="json">Specifica JSON</option></select></label><label>Separatore delle intestazioni<select id="payrollSpecDelimiter"><option value=";">Punto e virgola (;)</option><option value=",">Virgola (,)</option><option value="tab">Tabulazione</option></select></label><label>File facoltativo<input id="payrollSpecFile" type="file" accept=".csv,.txt,.json"></label><label class="payroll-wide">Intestazioni o specifica<textarea id="payrollSpecText" rows="4" placeholder="Matricola;Data;Causale;Ore"></textarea></label></div><div class="actions"><button type="button" class="btn" id="payrollSpecRead">Leggi e prepara la bozza</button><button type="button" class="btn" id="payrollSpecDownload">Scarica le specifiche salvate</button></div><div id="payrollSpecNotice" role="status"></div></details></div><label class="check payroll-attestation" id="payrollConnectorAttestation"><input type="checkbox" id="payrollConnectorConfirm" ${d.connectorConfirmed?'checked':''}>Ho verificato con il consulente questa versione: intestazioni e ordine, associazioni, tipi, lunghezze, separatori, codifica e formato date.</label></section>`;
 $('#payrollConnectorMode').onchange=e=>{
  connector.mode=e.target.value;cfg.status='draft';$('#payrollStatus').value='draft';
  if(connector.mode==='consultant')connector.expected_columns=cfg.columns.map(c=>({header:c.label,type:payrollFieldType(c.field),required:['registration','day','payroll_code'].includes(c.field),max_length:null}));
  else{
   cfg.columns=cfg.columns.filter(c=>c.field);for(const field of ['template_version','center_code','registration','day','payroll_code'])if(!cfg.columns.some(c=>c.field===field))cfg.columns.push({field,label:({template_version:'Versione modello',center_code:'Codice centro',registration:'Matricola paghe',day:'Data',payroll_code:'Causale paghe'})[field]});
   Object.assign(connector,payrollDefaultConnector());
  }
  payrollInvalidate(d);payrollRenderConnector(cfg,d,selectedCenter,request,showColumns);showColumns();
 };
 for(const [selector,key] of [['#payrollProvider','provider'],['#payrollFormatName','format_name'],['#payrollFormatVersion','format_version'],['#payrollSpecificationReference','specification_reference'],['#payrollDateFormat','date_format'],['#payrollEncoding','encoding']])$(selector).oninput=e=>{connector[key]=e.target.value;payrollInvalidate(d)};
 $('#payrollConnectorConfirm').onchange=e=>{d.connectorConfirmed=e.target.checked};
 $('#payrollSpecFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>32768)throw Error('Il file deve essere al massimo di 32 KiB e contenere solo le intestazioni o le specifiche.');const text=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer());if(request!==payrollRequest||tab!=='paghe'||cid!==selectedCenter)return;$('#payrollSpecText').value=text;$('#payrollSpecKind').value=file.name.toLowerCase().endsWith('.json')?'json':'csv_header'}catch(x){if($('#payrollSpecNotice'))$('#payrollSpecNotice').textContent='File non letto: '+(x instanceof TypeError?'salvalo con codifica UTF-8.':x.message)}};
 $('#payrollSpecRead').onclick=async()=>{
  const button=$('#payrollSpecRead');button.disabled=true;
  try{
   const result=await api('payroll_spec_preview',{cid:selectedCenter,kind:$('#payrollSpecKind').value,text:$('#payrollSpecText').value,delimiter:$('#payrollSpecDelimiter').value==='tab'?'\t':$('#payrollSpecDelimiter').value});
   if(request!==payrollRequest||tab!=='paghe'||cid!==selectedCenter)return;
   cfg.connector=result.connector;cfg.columns=result.columns;cfg.delimiter=result.delimiter;cfg.decimal_separator=result.decimal_separator;cfg.status='draft';cfg.confirmation_note='';
   payrollInvalidate(d);await renderPayroll();if($('#payrollSpecNotice'))$('#payrollSpecNotice').textContent=result.notice+' '+result.unmapped+' colonne da associare.';toast('Specifiche lette nella bozza. Verifica ogni associazione prima di salvare.');
  }catch(x){if($('#payrollSpecNotice'))$('#payrollSpecNotice').textContent=x.message}finally{if(button.isConnected)button.disabled=false}
 };
 $('#payrollSpecDownload').onclick=async()=>{try{if(d.dirty)throw Error('Salva il modello prima di scaricarne le specifiche.');const spec=await api('payroll_specification?'+new URLSearchParams({cid:selectedCenter}));downloadText('Specifica_paghe.json',JSON.stringify(spec,null,2),'application/json;charset=utf-8')}catch(x){$('#payrollSpecNotice').textContent=x.message}};
 payrollConnectorVisibility(cfg);
}
function payrollFieldType(field){return ['template_version','overnight','pause_minutes','worked_minutes','work_shifts','absence_slots','absence_days','credited_minutes','holiday'].includes(field)?'integer':['worked_hours','weekly_hours','part_time_percent'].includes(field)?'decimal':field==='day'?'date':'text'}
function payrollRenderColumns(cfg,data,fields,d,showColumns){
 const consultant=cfg.connector.mode==='consultant',expected=cfg.connector.expected_columns;
 const typeLabel={text:'Testo',integer:'Intero',decimal:'Decimale',date:'Data'};
 $('#payrollColumns').innerHTML=`<div class="table-scroll"><table class="data-table"><thead><tr><th>Dato del registro</th><th>Intestazione del file</th>${consultant?'<th>Regole richieste dal consulente</th>':''}<th>Ordine</th></tr></thead><tbody>${cfg.columns.map((c,i)=>{
  const label=fields[c.field]?.label||'Da associare',rule=expected[i];
  return `<tr><td>${consultant?`<select data-payroll-map="${i}" aria-label="Dato per ${esc(c.label)}"><option value="">Da associare</option>${data.fields.map(f=>`<option value="${f.id}" ${f.id===c.field?'selected':''} ${f.id!==c.field&&cfg.columns.some(other=>other.field===f.id)?'disabled':''}>${esc(f.label)}</option>`).join('')}</select>`:`${esc(label)}${fields[c.field]?.required?' <small class="muted">obbligatorio</small>':''}`}</td><td><input data-payroll-label="${i}" value="${esc(c.label)}" maxlength="120" required aria-label="Intestazione ${esc(label)}"></td>${consultant?`<td class="payroll-column-rule"><label>Tipo<select data-payroll-type="${i}">${Object.entries(typeLabel).map(([v,l])=>`<option value="${v}" ${rule?.type===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Massimo caratteri<input type="number" min="1" max="2000" step="1" data-payroll-max="${i}" value="${rule?.max_length??''}" placeholder="Nessun limite"></label><label class="check"><input type="checkbox" data-payroll-required="${i}" ${rule?.required?'checked':''}>Obbligatorio</label></td>`:''}<td><div class="actions"><button type="button" class="btn small" data-payroll-up="${i}" ${i===0?'disabled':''} aria-label="Sposta ${esc(label)} sopra">↑</button><button type="button" class="btn small" data-payroll-down="${i}" ${i===cfg.columns.length-1?'disabled':''} aria-label="Sposta ${esc(label)} sotto">↓</button>${!consultant&&fields[c.field]?.required?'':`<button type="button" class="btn small" data-payroll-remove="${i}" aria-label="Rimuovi ${esc(label)}">Rimuovi</button>`}</div></td></tr>`
 }).join('')}</tbody></table></div>`;
 const available=data.fields.filter(f=>!cfg.columns.some(c=>c.field===f.id));$('#payrollAddField').innerHTML=available.map(f=>`<option value="${f.id}">${esc(f.label)}</option>`).join('');$('#payrollAddColumn').disabled=!available.length||cfg.columns.length>=data.fields.length;$('#payrollAddExpected').disabled=cfg.columns.length>=data.fields.length;
 document.querySelectorAll('[data-payroll-label]').forEach(el=>el.oninput=()=>{const i=+el.dataset.payrollLabel;cfg.columns[i].label=el.value;if(consultant)expected[i].header=el.value;payrollInvalidate(d)});
 document.querySelectorAll('[data-payroll-map]').forEach(el=>el.onchange=()=>{cfg.columns[+el.dataset.payrollMap].field=el.value;payrollInvalidate(d);showColumns()});
 document.querySelectorAll('[data-payroll-type]').forEach(el=>el.onchange=()=>{expected[+el.dataset.payrollType].type=el.value;payrollInvalidate(d)});
 document.querySelectorAll('[data-payroll-max]').forEach(el=>el.oninput=()=>{expected[+el.dataset.payrollMax].max_length=el.value===''?null:Number(el.value);payrollInvalidate(d)});
 document.querySelectorAll('[data-payroll-required]').forEach(el=>el.onchange=()=>{expected[+el.dataset.payrollRequired].required=el.checked;payrollInvalidate(d)});
 const move=(i,delta)=>{[cfg.columns[i],cfg.columns[i+delta]]=[cfg.columns[i+delta],cfg.columns[i]];if(consultant)[expected[i],expected[i+delta]]=[expected[i+delta],expected[i]];payrollInvalidate(d);showColumns()};
 document.querySelectorAll('[data-payroll-up]').forEach(el=>el.onclick=()=>move(+el.dataset.payrollUp,-1));document.querySelectorAll('[data-payroll-down]').forEach(el=>el.onclick=()=>move(+el.dataset.payrollDown,1));document.querySelectorAll('[data-payroll-remove]').forEach(el=>el.onclick=()=>{const i=+el.dataset.payrollRemove;cfg.columns.splice(i,1);if(consultant)expected.splice(i,1);payrollInvalidate(d);showColumns()});payrollConnectorVisibility(cfg);
}
function payrollFormatValue(value,column,format){
 if(!format)return value;
 if(column.type==='date'&&format.date_format==='DD/MM/YYYY')return String(value).split('-').reverse().join('/');
 if(column.type==='decimal'&&typeof value==='number')return String(Number(value.toFixed(6))).replace('.',format.decimal_separator);
 return value;
}
function payrollFormatDescription(p){
 if(!p.connector)return '';
 const c=p.connector,f=p.output_format;
 return `<div class="note">${c.mode==='consultant'?`Gestionale ${esc(c.provider||'da definire')} · ${esc(c.format_name||'tracciato da definire')} ${esc(c.format_version)} · ${p.connector_status==='verified'?'specifiche verificate':'da concordare'}`:'Modello generico · compatibilità con il gestionale del consulente da verificare'}<br>CSV: ${esc(f.encoding)} · ${f.delimiter==='\t'?'tabulazione':f.delimiter===';'?'punto e virgola':'virgola'} · decimali ${f.decimal_separator===','?'con virgola':'con punto'} · date ${esc(f.date_format)}.</div>`;
}
